content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius: 8px;
  --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --primary-color: #60a5fa;
    --primary-hover: #3b82f6;
    --danger-color: #f87171;
    --danger-hover: #ef4444;
    --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.4), 0 1px 2px -1px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -4px rgba(0, 0, 0, 0.5);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-color);
}

::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

.app-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.board-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

@media (min-width: 768px) {
  .board-header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.board-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.add-task-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  width: 100%;
}

@media (min-width: 768px) {
  .add-task-form {
    width: auto;
  }
}

.form-input,
.form-select,
.form-textarea {
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 0.9rem;
  background-color: var(--card-bg);
  color: var(--text-main);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  width: 100%;
}

@media (min-width: 768px) {
  .form-input,
  .form-select,
  .form-textarea {
    width: auto;
  }
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
}

.form-input {
  flex: 1;
  min-width: 200px;
}

.form-select {
  cursor: pointer;
}

.form-textarea {
  width: 100%;
  resize: vertical;
  min-height: 60px;
}

.btn {
  padding: 8px 16px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  background-color: var(--card-bg);
  color: var(--text-main);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s, box-shadow 0.2s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn:hover {
  background-color: var(--border-color);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.4);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
}

.kanban-board {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  align-items: start;
}

@media (min-width: 768px) {
  .kanban-board {
    grid-template-columns: repeat(3, 1fr);
  }
}

.kanban-column {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  min-height: 500px;
  box-shadow: var(--shadow);
}

.column-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--border-color);
}

.column-header h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
}

.column-header .badge {
  background-color: var(--border-color);
  color: var(--text-main);
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-height: 100px;
}

.task-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
  cursor: grab;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid var(--border-color);
  transition: transform 0.2s, box-shadow 0.2s;
}

.task-card:active {
  cursor: grabbing;
}

.task-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.task-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  word-break: break-word;
}

.task-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  word-break: break-word;
  white-space: pre-wrap;
}

.task-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid var(--border-color);
}

.badge {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-low {
  background-color: #e0f2fe;
  color: #0369a1;
}

.badge-medium {
  background-color: #fef9c3;
  color: #a16207;
}

.badge-high {
  background-color: #fee2e2;
  color: #b91c1c;
}

@media (prefers-color-scheme: dark) {
  .badge-low {
    background-color: #0369a1;
    color: #e0f2fe;
  }
  .badge-medium {
    background-color: #a16207;
    color: #fef9c3;
  }
  .badge-high {
    background-color: #b91c1c;
    color: #fee2e2;
  }
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: 'todo' | 'in-progress' | 'done';
  priority: 'low' | 'medium' | 'high';
  dueDate?: string;
  assignee?: string;
}

export interface Column {
  id: 'todo' | 'in-progress' | 'done';
  title: string;
}

import { useState, useEffect } from 'react';
import { Task } from '../types';

interface TaskCardProps {
  task: Task;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDelete: (id: string) => void;
  onUpdate?: (task: Task) => void;
}

export default function TaskCard({ task, onDragStart, onDelete, onUpdate }: TaskCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [title, setTitle] = useState(task.title);
  const [description, setDescription] = useState(task.description);

  useEffect(() => {
    setTitle(task.title);
    setDescription(task.description);
  }, [task.title, task.description]);

  const handleSave = () => {
    if (!title.trim()) return;
    const updatedTask: Task = {
      ...task,
      title: title.trim(),
      description: description.trim(),
    };
    if (onUpdate) {
      onUpdate(updatedTask);
    }
    setIsEditing(false);
  };

  const getBadgeClass = (priority: Task['priority']) => {
    switch (priority) {
      case 'low':
        return 'badge badge-low';
      case 'medium':
        return 'badge badge-medium';
      case 'high':
        return 'badge badge-high';
      default:
        return 'badge';
    }
  };

  const getPriorityLabel = (priority: Task['priority']) => {
    switch (priority) {
      case 'low':
        return '低';
      case 'medium':
        return '中';
      case 'high':
        return '高';
      default:
        return priority;
    }
  };

  return (
    <div
      className="task-card"
      draggable={!isEditing}
      onDragStart={(e) => onDragStart(e, task.id)}
    >
      {isEditing ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <input
            type="text"
            className="form-input"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="タスク名"
          />
          <textarea
            className="form-textarea"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="詳細説明"
          />
          <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
            <button
              className="btn"
              style={{ padding: '4px 8px', fontSize: '0.75rem' }}
              onClick={() => {
                setTitle(task.title);
                setDescription(task.description);
                setIsEditing(false);
              }}
              aria-label="編集をキャンセル"
            >
              キャンセル
            </button>
            <button
              className="btn btn-primary"
              style={{ padding: '4px 8px', fontSize: '0.75rem' }}
              onClick={handleSave}
              aria-label="変更を保存"
            >
              保存
            </button>
          </div>
        </div>
      ) : (
        <>
          <div className="task-title">{task.title}</div>
          {task.description && <div className="task-desc">{task.description}</div>}
          <div className="task-footer">
            <span className={getBadgeClass(task.priority)}>
              優先度: {getPriorityLabel(task.priority)}
            </span>
            <div style={{ display: 'flex', gap: '4px' }}>
              <button
                className="btn"
                style={{ padding: '4px 8px', fontSize: '0.75rem' }}
                onClick={() => setIsEditing(true)}
                aria-label="タスクを編集"
              >
                編集
              </button>
              <button
                className="btn"
                style={{ padding: '4px 8px', fontSize: '0.75rem' }}
                onClick={() => onDelete(task.id)}
                aria-label="タスクを削除"
              >
                削除
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Task, Column } from '../types';
import TaskCard from './TaskCard';

interface KanbanColumnProps {
  column: Column;
  tasks: Task[];
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent, status: Column['id']) => void;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDeleteTask: (id: string) => void;
  onUpdateTask?: (task: Task) => void;
}

export default function KanbanColumn({
  column,
  tasks,
  onDragOver,
  onDrop,
  onDragStart,
  onDeleteTask,
  onUpdateTask,
}: KanbanColumnProps) {
  const [isOver, setIsOver] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    onDragOver(e);
    setIsOver(true);
  };

  const handleDragLeave = () => {
    setIsOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsOver(false);
    onDrop(e, column.id);
  };

  return (
    <div
      className="kanban-column"
      style={{
        borderColor: isOver ? 'var(--primary-color)' : undefined,
        backgroundColor: isOver ? 'rgba(59, 130, 246, 0.05)' : undefined,
        transition: 'background-color 0.2s, border-color 0.2s',
      }}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="column-header">
        <h2>{column.title}</h2>
        <span className="badge">{tasks.length}</span>
      </div>
      <div className="task-list">
        {tasks.length === 0 ? (
          <div style={{ padding: '24px 0', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
            タスクがありません
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onDelete={onDeleteTask}
              onUpdate={onUpdateTask}
            />
          ))
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Task, Column } from './types';
import KanbanColumn from './components/KanbanColumn';
import './index.css';

const COLUMNS: Column[] = [
  { id: 'todo', title: '未着手' },
  { id: 'in-progress', title: '作業中' },
  { id: 'done', title: '完了' },
];

const INITIAL_TASKS: Task[] = [
  {
    id: '1',
    title: 'プロジェクトの要件定義',
    description: 'クライアントとのミーティング内容をまとめ、要件定義書を作成する。',
    status: 'todo',
    priority: 'high',
  },
  {
    id: '2',
    title: 'ワイヤーフレーム作成',
    description: 'Figmaを使用して画面遷移図とモックアップを作成する。',
    status: 'in-progress',
    priority: 'medium',
  },
  {
    id: '3',
    title: 'リポジトリの初期設定',
    description: 'Git repositoryの作成とReactプロジェクトの基本構成をセットアップ。',
    status: 'done',
    priority: 'low',
  },
];

export default function App() {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('kanban_tasks');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error(e);
      }
    }
    return INITIAL_TASKS;
  });

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<Task['priority']>('medium');
  const [status, setStatus] = useState<Task['status']>('todo');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('kanban_tasks', JSON.stringify(tasks));
  }, [tasks]);

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      setError('タスク名を入力してください。');
      return;
    }
    setError(null);

    const newTask: Task = {
      id: Date.now().toString(),
      title: title.trim(),
      description: description.trim(),
      status,
      priority,
    };

    setTasks([...tasks, newTask]);
    setTitle('');
    setDescription('');
    setPriority('medium');
    setStatus('todo');
  };

  const handleDeleteTask = (id: string) => {
    setTasks(tasks.filter((task) => task.id !== id));
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(tasks.map((task) => (task.id === updatedTask.id ? updatedTask : task)));
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData('text/plain', id);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, newStatus: Column['id']) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    if (!taskId) return;

    setTasks(
      tasks.map((task) =>
        task.id === taskId ? { ...task, status: newStatus } : task
      )
    );
  };

  return (
    <div className="app-container">
      <header className="board-header">
        <h1>カンバンボード</h1>
        <form className="add-task-form" onSubmit={handleAddTask}>
          <input
            type="text"
            className="form-input"
            placeholder="タスク名を入力..."
            value={title}
            onChange={(e) => {
              setTitle(e.target.value);
              if (error) setError(null);
            }}
          />
          <select
            className="form-select"
            value={status}
            onChange={(e) => setStatus(e.target.value as Task['status'])}
          >
            <option value="todo">未着手</option>
            <option value="in-progress">作業中</option>
            <option value="done">完了</option>
          </select>
          <select
            className="form-select"
            value={priority}
            onChange={(e) => setPriority(e.target.value as Task['priority'])}
          >
            <option value="low">低</option>
            <option value="medium">中</option>
            <option value="high">高</option>
          </select>
          <textarea
            className="form-textarea"
            placeholder="詳細説明..."
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          {error && (
            <div style={{ color: 'var(--danger-color)', fontSize: '0.85rem', width: '100%' }}>
              {error}
            </div>
          )}
          <button type="submit" className="btn btn-primary" style={{ width: '100%' }}>
            タスクを追加
          </button>
        </form>
      </header>

      <main className="kanban-board">
        {COLUMNS.map((column) => (
          <KanbanColumn
            key={column.id}
            column={column}
            tasks={tasks.filter((task) => task.status === column.id)}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
            onDragStart={handleDragStart}
            onDeleteTask={handleDeleteTask}
            onUpdateTask={handleUpdateTask}
          />
        ))}
      </main>
    </div>
  );
}
